<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/includes/admin_auth.php';
require_once dirname(__DIR__) . '/includes/resources_page_data.php';
require_once dirname(__DIR__) . '/includes/resources_blog_data.php';
require_once __DIR__ . '/_layout.php';
require_once __DIR__ . '/_media_picker.php';

$dbError = null;
$pdo = web_db($dbError);
if (!$pdo) { header('Location: login.php'); exit; }
web_migrate($pdo);
artdon_resource_page_seed($pdo);
$user = web_require_admin($pdo);
$pages = artdon_resource_page_all($pdo);
$slug = trim((string)($_GET['slug'] ?? ($pages[0]['slug'] ?? 'resources')));
$page = artdon_resource_page_get($pdo, $slug);

function rsp_e(mixed $value): string { return web_e((string)$value); }
function rsp_url(string $path): string
{
    $path = trim($path);
    if ($path === '') return '';
    if (preg_match('#^(?:https?:)?//#i', $path) || str_starts_with($path, 'data:')) return $path;
    return '../' . ltrim($path, '/');
}
function rsp_img(string $path): string
{
    $url = rsp_url($path);
    return $url !== '' ? '<img src="'.rsp_e($url).'" alt="">' : '<span>No image</span>';
}
function rsp_front_url(string $slug): string
{
    return match($slug) {
        'downloads' => '../resources-downloads.php',
        'blog' => '../resources-blog.php',
        'blog-detail' => '../resources-blog-detail.php?slug=how-to-choose-right-beam-angle',
        'faq' => '../resources-faq.php',
        'videos' => '../resources-videos.php',
        default => '../resources.php',
    };
}
$contentJson = json_encode((array)$page['content'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
$pageContent = is_array($page['content'] ?? null) ? $page['content'] : [];
$browseResources = is_array($pageContent['browse_resources'] ?? null) ? array_values($pageContent['browse_resources']) : [];
$popularDownloads = is_array($pageContent['popular_downloads'] ?? null) ? array_values($pageContent['popular_downloads']) : [];
$latestArticles = is_array($pageContent['latest_articles'] ?? null) ? array_values($pageContent['latest_articles']) : [];
$featuredVideos = is_array($pageContent['featured_videos'] ?? null) ? array_values($pageContent['featured_videos']) : [];
$downloadSections = is_array($pageContent['sections'] ?? null) ? array_values($pageContent['sections']) : [];
$blogCategoryDefaults = artdon_resource_blog_categories();
$blogCategories = [];
foreach ($blogCategoryDefaults as $key => $label) {
    $row = is_array($pageContent['blog_categories'][$key] ?? null) ? $pageContent['blog_categories'][$key] : [];
    $blogCategories[$key] = [
        'label'=>trim((string)($row['label'] ?? '')) ?: $label,
        'section_title'=>trim((string)($row['section_title'] ?? '')) ?: $label,
        'view_all_text'=>trim((string)($row['view_all_text'] ?? '')) ?: 'VIEW ALL',
        'icon'=>trim((string)($row['icon'] ?? '')) ?: $key,
        'sort_order'=>(int)($row['sort_order'] ?? (count($blogCategories) + 1) * 10),
        'is_visible'=>!isset($row['is_visible']) || (int)$row['is_visible'] === 1,
    ];
}
for ($i=count($browseResources); $i<4; $i++) $browseResources[$i] = ['key'=>'','title'=>'','items'=>[],'button'=>'','url'=>'','icon'=>'download'];
for ($i=count($popularDownloads); $i<1; $i++) $popularDownloads[$i] = ['title'=>'','type'=>'PDF','size'=>'','image'=>'','url'=>'','sort_order'=>$i];
for ($i=count($latestArticles); $i<3; $i++) $latestArticles[$i] = ['category'=>'','title'=>'','date'=>'','image'=>'','slug'=>'','url'=>''];
for ($i=count($featuredVideos); $i<4; $i++) $featuredVideos[$i] = ['title'=>'','image'=>'','duration'=>'','url'=>''];
for ($i=count($downloadSections); $i<3; $i++) $downloadSections[$i] = ['key'=>'','title'=>'','intro'=>'','cover'=>'','items'=>[]];
foreach ($downloadSections as $di => $section) {
    $cardsForSection = is_array($section['cards'] ?? null) ? array_values($section['cards']) : [];
    if (!$cardsForSection) {
        foreach (array_values((array)($section['items'] ?? [])) as $title) {
            $cardsForSection[] = ['title'=>(string)$title,'description'=>'','url'=>'','type'=>'PDF','size'=>'','image'=>'','sort_order'=>count($cardsForSection)];
        }
    }
    for ($ci=count($cardsForSection); $ci<1; $ci++) $cardsForSection[$ci] = ['title'=>'','description'=>'','url'=>'','type'=>'PDF','size'=>'','image'=>'','sort_order'=>$ci];
    $downloadSections[$di]['cards'] = $cardsForSection;
}
$cards = [
    ['Hero 首屏', trim((string)$page['hero_title']) !== '', (string)$page['hero_title']],
    ['CTA', trim((string)$page['cta_title']) !== '', (string)$page['cta_title']],
    ['模块内容', trim((string)$contentJson) !== '', 'Browse / Popular Downloads / Articles / Videos'],
    ['SEO', trim((string)$page['seo_title']) !== '', (string)$page['seo_title']],
];

admin_page_start('Resources 页面管理', 'resources_pages', $user);
admin_notice();
