ndary" data-media-clear>清空</button></div><figure class="media-field-preview"></figure></div></article>';}function popularCardHtml(index){var n='popular_downloads['+index+']';return '<article class="rsp-repeat rsp-download-card"><div class="rsp-card-head"><h4>下载卡 '+(Number(index)+1)+'</h4><button type="button" class="admin-button-danger" data-popular-download-remove>删除</button></div><div class="rsp-two"><label class="field"><span>标题</span><input name="'+n+'[title]" value=""></label><label class="field"><span>排序</span><input type="number" name="'+n+'[sort_order]" value="'+index+'"></label></div><div class="rsp-two"><label class="field"><span>文件类型</span><input name="'+n+'[type]" value="PDF"></label><label class="field"><span>文件大小</span><input name="'+n+'[size]" value=""></label></div><div class="field"><span>下载文件</span><div class="rsp-media-row"><input class="media-path-input" name="'+n+'[url]" value=""><button type="button" class="admin-button-secondary" data-media-open data-media-type="file" data-media-usage="downloads">从媒体库选择</button><button type="button" class="admin-button-secondary" data-media-clear>清空</button></div><input type="file" name="popular_download_file_'+index+'" accept=".pdf,.zip,.ies,.ldt,.dwg,.dxf,.xlsx,.docx,.txt,.csv"><figure class="media-field-preview rsp-file-preview"></figure></div><div class="field"><span>封面图</span><div class="rsp-media-row"><input class="media-path-input" name="'+n+'[image]" value=""><button type="button" class="admin-button-secondary" data-media-open data-media-type="image" data-media-usage="images">从媒体库选择</button><button type="button" class="admin-button-secondary" data-media-clear>清空</button></div><figure class="media-field-preview"></figure></div></article>';}document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('[data-rsp-open]')){open();return;}if(e.target.closest&&e.target.closest('[data-rsp-close]')){close();return;}var add=e.target.closest&&e.target.closest('[data-download-card-add]');if(add){var section=add.getAttribute('data-download-card-add');var wrap=document.querySelector('[data-download-cards="'+section+'"]');if(wrap){var index=Number(wrap.getAttribute('data-next-index')||0);wrap.insertAdjacentHTML('beforeend',downloadCardHtml(section,index));wrap.setAttribute('data-next-index',String(index+1));}return;}var addPopular=e.target.closest&&e.target.closest('[data-popular-download-add]');if(addPopular){var popularWrap=document.querySelector('[data-popular-downloads]');if(popularWrap){var pi=Number(popularWrap.getAttribute('data-next-index')||0);popularWrap.insertAdjacentHTML('beforeend',popularCardHtml(pi));popularWrap.setAttribute('data-next-index',String(pi+1));}return;}var remove=e.target.closest&&e.target.closest('[data-download-card-remove],[data-popular-download-remove]');if(remove){var card=remove.closest('.rsp-download-card');if(card&&confirm('确认删除这张下载卡？保存后前台同步删除。'))card.remove();return;}});})();</script>
<script>(function(){function addAltFields(){var saved=window.RSP_DOWNLOAD_ALTS||{};document.querySelectorAll('.rsp-download-card').forEach(function(card){var title=card.querySelector('input[name$="[title]"]');if(!title)return;var altName=title.name.replace(/\[title\]$/,'[alt]');if(card.querySelector('input[name="'+altName.replace(/"/g,'\\"')+'"]'))return;var field=document.createElement('label');field.className='field';field.innerHTML='<span>文件 ALT / 说明</span><input name="'+altName+'" value="">';var input=field.querySelector('input');input.value=saved[altName]||'';var desc=card.querySelector('textarea[name$="[description]"]');var descField=desc&&desc.closest?desc.closest('.field'):null;if(descField&&descField.parentNode){descField.parentNode.insertBefore(field,descField.nextSibling);}else{var firstRow=title.closest('.rsp-two');firstRow.parentNode.insertBefore(field,firstRow.nextSibling);}});}document.addEventListener('DOMContentLoaded',addAltFields);document.addEventListener('click',function(){setTimeout(addAltFields,0);});})();</script>
